        let Some(Validation::Betterleaks(mut validation)) = rule.validation else {
            panic!("expected Betterleaks validation");
        };
        replace_string_literal(
            &mut validation.expression,
            "https://api.airtable.com/v0/meta/whoami",
            &format!("http://{address}/validate"),
        );
